function makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation) {
  let client;
  client = new JsonRpcWebSocketClient(endpoint.url, {
    bearerToken: endpoint.bearerToken || null,
    logger: relayLogger(config),
    onNotification: (message) => {
      if (isSessionActive(session, downstreamWs, generation)) {
        sendJson(downstreamWs, message);
      }
    },
    onRequest: (message) => {
      if (isSessionActive(session, downstreamWs, generation)) {
        sendJson(downstreamWs, message);
      }
    },
    onClose: () => {
      handleSessionUpstreamClose(config, session, downstreamWs, client);
    },
  });
  return client;
}

function handleSessionUpstreamClose(config, session, downstreamWs, closedClient) {
  if (session.closing || session.upstream !== closedClient) {
    return;
  }
  session.upstream = null;
  if (!isWebSocketOpen(downstreamWs)) {
    return;
  }
  if (!session.endpoint || !session.resumeParams?.threadId) {
    config.statusTracker?.recordUpstreamError(new Error("upstream closed"), {
      subsystem: "live-upstream",
    });
    downstreamWs.close(1011, "upstream closed");
    return;
  }
  if (session.retryTask) {
    return;
  }
  session.retryTask = recoverSessionUpstream(config, session, downstreamWs, session.generation);
}

async function recoverSessionUpstream(config, session, downstreamWs, generation) {
  const endpoint = session.endpoint;
  const resumeParams = session.resumeParams;
  let lastError = null;
  config.statusTracker?.recordReconnect({
    active: true,
    attempts: 0,
  });

  for (let attempt = 1; attempt <= UPSTREAM_RECONNECT_ATTEMPTS; attempt += 1) {
    if (session.closing || session.generation !== generation || !isWebSocketOpen(downstreamWs)) {
      session.retryTask = null;
      config.statusTracker?.recordReconnect({
        active: false,
        attempts: attempt - 1,
      });
      return;
    }

    const client = makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation);
    try {
      await initializeClient(client);
      await client.request("thread/resume", resumeParams);
      if (!isSessionActive(session, downstreamWs, generation)) {
        client.close();
        session.retryTask = null;
        return;
      }
      session.upstream = client;
      session.retryTask = null;
      config.statusTracker?.recordReconnect({
        active: false,
        attempts: attempt,
      });
      relayLogger(config).info("upstream.recovery_succeeded", {
        threadId: resumeParams.threadId,
        endpointUrl: endpoint.url,
        attempt,
      });
      return;
    } catch (error) {
      lastError = error;
      config.statusTracker?.recordUpstreamError(error, {
        subsystem: "live-upstream",
        threadId: resumeParams.threadId,
        endpointUrl: endpoint.url,
        attempt,
      });
      client.close();
      const delayMs = upstreamReconnectDelayMs(attempt);
      config.statusTracker?.recordReconnect({
        active: true,
        attempts: attempt,
        nextRetryAt: new Date(Date.now() + delayMs).toISOString(),
      });
      await sleep(delayMs);
    }
  }

  session.retryTask = null;
  config.statusTracker?.recordReconnect({
    active: false,
    attempts: UPSTREAM_RECONNECT_ATTEMPTS,
  });
  relayLogger(config).error("upstream.recovery_failed", {
    threadId: resumeParams.threadId,
    endpointUrl: endpoint.url,
    error: lastError,
  });
  if (!session.closing && session.generation === generation && isWebSocketOpen(downstreamWs)) {
    downstreamWs.close(1011, "upstream recovery failed");
  }
}

async function forwardToActiveUpstream(session, method, params = {}) {
  if (!session.upstream?.isOpen()) {
    throw new Error(`${method} requires thread/resume on this connection first`);
  }
  return session.upstream.request(method, params);
}

async function handleRequest(config, method, params, session, downstreamWs) {
  switch (method) {
    case "initialize":
      return {
        userAgent: `codex_dock_relay/${RELAY_VERSION} (${os.type()} ${os.release()}; ${os.arch()})`,
        codexHome: process.env.CODEX_HOME || `${os.homedir()}/.codex`,
        platformFamily: "unix",
        platformOs: platformOs(),
      };
    case "thread/list":
      return aggregateThreadList(config, params || {});
    case "thread/loaded/list":
      return aggregateLoadedList(params || {}, relayLogger(config));
    case "thread/read":
      return aggregateThreadRead(config, params || {});
    case "thread/turns/list":
      return listThreadTurns(config, params || {});
    case "thread/resume":
      return resumeThread(config, params || {}, session, downstreamWs);
    case "thread/archive":
      return archiveThread(config, params || {});
    case "thread/unarchive":
      return unarchiveThread(config, params || {});
    case "audio/transcription/start":
      return session.realtimeTranscription.start(params || {});
    case "audio/transcription/append":
      return session.realtimeTranscription.append(params || {});
    case "audio/transcription/commit":
      return session.realtimeTranscription.commit(params || {});
    case "audio/transcription/cancel":
      return session.realtimeTranscription.cancel(params || {});
    case "turn/start":
    case "turn/steer":
    case "turn/interrupt":
      return forwardToActiveUpstream(session, method, params || {});
    default:
      throw Object.assign(new Error(`unsupported method: ${method}`), {
        code: -32601,
      });
  }
}

function assertAuthorized(request, token) {
  const header = request.headers.authorization || "";
  return header === `Bearer ${token}`;
}

function isPhoneRequestAuthorized(request, config) {
  if (config.phoneAuth === "none") {
    return true;
  }
  return assertAuthorized(request, config.relayBearerToken);
}

function startServer(config) {
  config.logger = relayLogger(config);
  const logger = config.logger;
  config.version = config.version || RELAY_VERSION;
  config.hostId = config.hostId || process.env.CODEX_DOCK_REAL_HOST_ID || os.hostname();
  config.hostName = config.hostName || process.env.CODEX_DOCK_REAL_HOST_NAME || config.hostId;
  config.openAIRealtimeTranscriptionModel = config.openAIRealtimeTranscriptionModel
    || DEFAULT_REALTIME_TRANSCRIPTION_MODEL;
  config.openAIRealtimeTranscriptionEndpoint = config.openAIRealtimeTranscriptionEndpoint
    || DEFAULT_REALTIME_TRANSCRIPTION_ENDPOINT;
  config.realtimeTranscriptionLanguage = config.realtimeTranscriptionLanguage
    || DEFAULT_REALTIME_TRANSCRIPTION_LANGUAGE;
  config.realtimeTranscriptionDelay = config.realtimeTranscriptionDelay
    || DEFAULT_REALTIME_TRANSCRIPTION_DELAY;
  config.statusTracker = config.statusTracker || createRelayStatusTracker();
  config.phoneAuth = parsePhoneAuthMode(config.phoneAuth || DEFAULT_PHONE_AUTH);
  if (config.phoneAuth === "bearer" && !config.relayBearerToken) {
    throw new Error("relayBearerToken is required when phoneAuth is bearer");
  }
  logger.info("relay.starting", {
    subsystem: "relay",
    hostId: config.hostId,
    listenHost: config.listenHost,
    port: config.port,
    historyUrl: config.historyUrl,
    phoneAuth: config.phoneAuth,
    advertiseBonjour: config.advertiseBonjour !== false,
  });

  const sessions = new Set();
  const downstreamSockets = new Set();

  async function writeStatusResponse(response) {
    await checkRawAppServerHealth(config, config.statusTracker);
    try {
      const live = await collectLiveRows(logger);
      config.statusTracker.recordLiveDiscovery({
        status: "up",
        ok: true,
        endpoints: live.endpoints.length,
        failedEndpoints: live.failedEndpoints,
        rows: live.rows.length,
      });
    } catch (error) {
      config.statusTracker.recordLiveDiscovery({
        status: "down",
        ok: false,
        error,
      });
    }
    response.writeHead(200, { "content-type": "application/json" });
    response.end(JSON.stringify(config.statusTracker.snapshot(config, {
      downstreamActive: downstreamSockets.size,
      upstreamActive: [...sessions].filter((session) => session.upstream?.isOpen()).length,
    })));
  }

  const server = http.createServer((request, response) => {
    if (request.url === "/readyz") {
      response.writeHead(200, { "content-type": "application/json" });
      response.end(JSON.stringify({
        ok: true,
        service: "codex-dock-relay",
        auth: config.phoneAuth,
      }));
      return;
    }
    if (request.url === "/healthz") {
      response.writeHead(200, { "content-type": "application/json" });
      response.end(JSON.stringify({
        ok: true,
        service: "codex-dock-relay",
        auth: config.phoneAuth,
        staticConfig: {
          ok: true,
          historyConfigured: Boolean(config.historyUrl),
          transcriptionConfigured: Boolean(config.openAIRealtimeTranscriptionModel),
        },
      }));
      return;
    }
    if (request.url === "/statusz") {
      writeStatusResponse(response).catch((error) => {
        logger.error("statusz.failed", { error });
        response.writeHead(500, { "content-type": "application/json" });
        response.end(JSON.stringify({
          ok: false,
          service: "codex-dock-relay",
          error: "status unavailable",
        }));
      });

      byUrl.set(endpoint.url, endpoint);
    }
  }
  return [...byUrl.values()].sort((lhs, rhs) => lhs.pid - rhs.pid);
}

async function withClient(url, options, operation) {
  const client = new JsonRpcWebSocketClient(url, options);
  await initializeClient(client);
  try {
    return await operation(client);
  } finally {
    client.close();
  }
}

async function initializeClient(client) {
  await client.connect();
  await client.request("initialize", {
    clientInfo: {
      name: "codex_dock_relay",
      title: "Codex Dock Relay",
      version: RELAY_VERSION,
    },
    capabilities: {
      experimentalApi: true,
      requestAttestation: false,
    },
  });
  client.notify("initialized");
}

async function readLoadedRows(endpoint, logger = defaultRelayLogger) {
  return withClient(endpoint.url, { logger }, async (client) => {
    const loaded = await client.request("thread/loaded/list", { limit: 500 });
    const results = await Promise.allSettled((loaded.data || []).map((threadId) => (
      client.request("thread/read", {
        threadId,
        includeTurns: false,
      })
    )));
    const rows = [];
    for (let index = 0; index < results.length; index += 1) {
      const result = results[index];
      if (result.status === "rejected") {
        logger.warn("live.thread_read_failed", {
          threadId: loaded.data[index],
          endpointUrl: endpoint.url,
          error: result.reason,
        });
        continue;
      }
      if (result.value?.thread?.id) {
        rows.push({ ...result.value.thread, dockRelaySource: endpoint });
      }
    }
    return Promise.all(rows.map((row) => enrichRowAttention(row, endpoint, logger)));
  });
}

async function pendingRequestsForActiveThread(endpoint, threadId, logger = defaultRelayLogger) {
  const requests = [];
  const client = new JsonRpcWebSocketClient(endpoint.url, {
    bearerToken: endpoint.bearerToken || null,
    logger,
    onRequest: (message) => {
      if (message?.params?.threadId === threadId) {
        requests.push(message);
      }
    },
  });
  try {
    await initializeClient(client);
    await client.request("thread/resume", { threadId, excludeTurns: true });
    await sleep(100);
    return requests;
  } finally {
    client.close();
  }
}

async function enrichRowAttention(row, endpoint, logger = defaultRelayLogger) {
  if (row?.status?.type !== "active") {
    return row;
  }
  const existingFlags = new Set(row.status.activeFlags || []);
  if (existingFlags.has("waitingOnApproval") || existingFlags.has("waitingOnUserInput")) {
    return row;
  }

  let requests;
  try {
    requests = await pendingRequestsForActiveThread(endpoint, row.id, logger);
  } catch (error) {
    logger.warn("live.pending_requests_failed", {
      threadId: row.id,
      endpointUrl: endpoint.url,
      error,
    });
    return row;
  }

  const flags = requests.flatMap(attentionFlagsForServerRequest);
  return mergeActiveFlags(row, flags);
}

async function collectLiveRows(logger = defaultRelayLogger) {
  const endpoints = discoverLoopbackEndpoints();
  const results = await Promise.allSettled(endpoints.map((endpoint) => readLoadedRows(endpoint, logger)));
  const rowsById = new Map();
  let failedEndpoints = 0;
  for (let index = 0; index < results.length; index += 1) {
    const result = results[index];
    if (result.status === "rejected") {
      failedEndpoints += 1;
      logger.warn("live.endpoint_query_failed", {
        endpointUrl: endpoints[index].url,
        error: result.reason,
      });
      continue;
    }
    for (const row of result.value) {
      rowsById.set(row.id, preferThread(row, rowsById.get(row.id)));
    }
  }
  return {
    endpoints,
    failedEndpoints,
    rows: [...rowsById.values()],
  };
}

async function readHistoryThreadList(config, params) {
  return withClient(
    config.historyUrl,
    { bearerToken: config.historyBearerToken, logger: relayLogger(config) },
    async (client) => client.request("thread/list", params),
  );
}

async function readHistoryThread(config, params) {
  return withClient(
    config.historyUrl,
    { bearerToken: config.historyBearerToken, logger: relayLogger(config) },
    async (client) => client.request("thread/read", params),
  );
}

async function readThreadTurnsFromEndpoint(endpoint, params, timeoutMs = undefined, logger = defaultRelayLogger) {
  return withClient(
    endpoint.url,
    { bearerToken: endpoint.bearerToken || null, timeoutMs, logger },
    async (client) => client.request("thread/turns/list", params),
  );
}

async function readThreadFromEndpoint(endpoint, params, logger = defaultRelayLogger) {
  return withClient(
    endpoint.url,
    { bearerToken: endpoint.bearerToken || null, logger },
    async (client) => client.request("thread/read", params),
  );
}

function sanitizeRelayFields(thread) {
  if (!thread || typeof thread !== "object") {
    return thread;
  }
  const { dockRelaySource, ...clean } = thread;
  return clean;
}

function shouldCollectLiveRowsForThreadList(params = {}) {
  return params.archived !== true;
}

function mergeLiveRowWithHistoryFreshness(liveRow, historyRow) {
  if (!historyRow) {
    return liveRow;
  }

  const historyTimestamp = rowTimestamp(historyRow);
  if (!Number.isFinite(historyTimestamp)) {
    return liveRow;
  }

  const liveTimestamp = rowTimestamp(liveRow);
  if (Number.isFinite(liveTimestamp) && historyTimestamp <= liveTimestamp) {
    return liveRow;
  }

  return {
    ...liveRow,
    updatedAt: historyTimestamp,
  };
}

function mergeThreadListRows(historyRows = [], liveRows = [], params = {}) {
  const historyById = new Map();
  for (const row of historyRows) {
    if (!row?.id) {
      continue;
    }
    const existing = historyById.get(row.id);
    if (!existing || rowTimestamp(row) >= rowTimestamp(existing)) {
      historyById.set(row.id, row);
    }
  }
  const freshenedLiveRows = liveRows.map((row) => (
    mergeLiveRowWithHistoryFreshness(row, historyById.get(row?.id))
  ));
  const liveIds = new Set(freshenedLiveRows.map((row) => row.id));
  const sortRows = (rows) => [...rows].sort((lhs, rhs) => {
    const timestampDelta = rowTimestamp(rhs) - rowTimestamp(lhs);
    if (timestampDelta !== 0) {
      return timestampDelta;
    }
    const statusDelta = statusPriority(lhs) - statusPriority(rhs);
    if (statusDelta !== 0) {
      return statusDelta;
    }
    return String(lhs.id || "").localeCompare(String(rhs.id || ""));
  });

  const sortedLiveRows = sortRows(freshenedLiveRows.map(sanitizeRelayFields));
  const historyOnlyRows = sortRows(historyRows.filter((row) => !liveIds.has(row.id)));
  const limit = parseLimit(params.limit, sortedLiveRows.length + historyOnlyRows.length || 1);
  return [
    ...sortedLiveRows.slice(0, limit),
    ...historyOnlyRows.slice(0, Math.max(0, limit - sortedLiveRows.length)),
  ];
}

async function enrichThreadListPreviews(config, rows, endpointByThreadId = new Map()) {
  const logger = relayLogger(config);
  return mapWithConcurrency(
    rows,
    THREAD_LIST_PREVIEW_ENRICH_CONCURRENCY,
    async (row) => {
      if (!row?.id) {
        return row;
      }
      const endpoint = endpointByThreadId.get(row.id) || {
        url: config.historyUrl,
        bearerToken: config.historyBearerToken,
      };
      try {
        const turns = await readThreadTurnsFromEndpoint(endpoint, {
          threadId: row.id,
          limit: THREAD_LIST_PREVIEW_TURNS_LIMIT,
        }, THREAD_LIST_PREVIEW_ENRICH_TIMEOUT_MS, logger);
        const preview = latestMeaningfulTextFromTurns(turns?.data);
        if (!preview) {
          return row;
        }
        return {
          ...row,
          preview,
        };
      } catch (error) {
        logger.warn("thread_list.preview_enrich_failed", {
          threadId: row.id,
          endpointUrl: endpoint.url,
          error,
        });
        return row;
      }
    },
  );
}

async function aggregateThreadList(config, params = {}) {
  const logger = relayLogger(config);
  if (!shouldCollectLiveRowsForThreadList(params)) {
    const history = await readHistoryThreadList(config, params);
    const data = await enrichThreadListPreviews(config, history.data || []);
    logger.info("thread_list.archived_loaded", {
      historyRows: history.data?.length || 0,
      liveRows: 0,
      returnedRows: data.length,
    });
    return {
      ...history,
      data,
    };
  }

  const [historyResult, liveResult] = await Promise.allSettled([
    readHistoryThreadList(config, params),
    collectLiveRows(logger),
  ]);
  if (historyResult.status === "rejected" && liveResult.status === "rejected") {
    throw new Error(
      `thread/list failed for history and live sources: history=${historyResult.reason?.message || historyResult.reason}; live=${liveResult.reason?.message || liveResult.reason}`,
    );
  }

  const history = historyResult.status === "fulfilled"
    ? historyResult.value
    : { data: [] };

  const live = liveResult.status === "fulfilled"
    ? liveResult.value
    : { endpoints: [], failedEndpoints: 1, rows: [] };

  if (historyResult.status === "rejected") {
    logger.warn("thread_list.history_failed", {
      error: historyResult.reason,
    });
  }
  if (liveResult.status === "rejected") {
    logger.warn("thread_list.live_failed", {
      error: liveResult.reason,
    });
  }

  const filteredLiveRows = live.rows.filter((row) => (
    threadMatchesSourceKinds(row, params.sourceKinds)
  ));
  const endpointByThreadId = new Map(
    filteredLiveRows
      .filter((row) => row?.id && row.dockRelaySource)
      .map((row) => [row.id, row.dockRelaySource]),
  );
  const data = await enrichThreadListPreviews(
    config,
    mergeThreadListRows(history.data || [], filteredLiveRows, params),
    endpointByThreadId,
  );
  logger.info("thread_list.loaded", {
    historyRows: history.data?.length || 0,
    liveRows: filteredLiveRows.length,
    endpoints: live.endpoints.length,
    failedEndpoints: live.failedEndpoints,
    returnedRows: data.length,
  });
  return {
    data,
    nextCursor: null,
    backwardsCursor: null,
  };
}

async function aggregateLoadedList(params = {}, logger = defaultRelayLogger) {
  const live = await collectLiveRows(logger);
  const ids = live.rows.map((row) => row.id);
  logger.info("thread_loaded_list.loaded", {
    liveRows: ids.length,
    endpoints: live.endpoints.length,
    failedEndpoints: live.failedEndpoints,
  });
  return paginateStrings(ids, params);
}

async function aggregateThreadRead(config, params = {}) {
  if (!params.threadId) {
    throw new Error("thread/read requires threadId");
  }
  const live = await collectLiveRows(relayLogger(config));
  const liveRow = live.rows.find((row) => row.id === params.threadId);
  if (liveRow) {
    if (params.includeTurns) {
      return readThreadFromEndpoint(liveRow.dockRelaySource, params, relayLogger(config));
    }
    return { thread: sanitizeRelayFields(liveRow) };
  }
  return readHistoryThread(config, params);
}

async function listThreadTurns(config, params = {}) {
  if (!params.threadId) {
    throw new Error("thread/turns/list requires threadId");
  }
  const endpoint = await endpointForThread(config, params.threadId);
  return readThreadTurnsFromEndpoint(endpoint, params, undefined, relayLogger(config));
}

async function endpointForThread(config, threadId) {
  const live = await collectLiveRows(relayLogger(config));
  const liveRow = live.rows.find((row) => row.id === threadId);
  if (liveRow?.dockRelaySource) {
    return liveRow.dockRelaySource;
  }
  return {
    url: config.historyUrl,
    bearerToken: config.historyBearerToken,
  };
}

async function archiveThread(config, params = {}) {
  if (!params.threadId) {
    throw new Error("thread/archive requires threadId");
  }
  const endpoint = await endpointForThread(config, params.threadId);
  return withClient(
    endpoint.url,
    { bearerToken: endpoint.bearerToken || null, logger: relayLogger(config) },
    async (client) => client.request("thread/archive", params),
  );
}

async function unarchiveThread(config, params = {}) {
  if (!params.threadId) {
    throw new Error("thread/unarchive requires threadId");
  }
  return withClient(
    config.historyUrl,
    { bearerToken: config.historyBearerToken, logger: relayLogger(config) },
    async (client) => client.request("thread/unarchive", params),
  );
}

export {
  aggregateLoadedList,
  aggregateThreadList,
  aggregateThreadRead,
  archiveThread,
  attentionFlagsForServerRequest,
  collectLiveRows,
  endpointForThread,
  initializeClient,
  listThreadTurns,
  mergeActiveFlags,
  mergeThreadListRows,
  parseLimit,
  pendingRequestsForActiveThread,
  preferThread,
  sanitizeRelayFields,
  shouldCollectLiveRowsForThreadList,
  statusPriority,
  unarchiveThread,
};

import WebSocket from "ws";

const DEFAULT_TIMEOUT_MS = 5_000;

class JsonRpcUpstreamError extends Error {
  constructor(method, upstreamError) {
    const message = upstreamError?.message || "upstream JSON-RPC error";
    super(`${method}: ${message}`);
    this.name = "JsonRpcUpstreamError";
    this.method = method;
    this.code = Number.isInteger(upstreamError?.code) ? upstreamError.code : -32000;
    this.data = upstreamError?.data;
    this.upstreamError = upstreamError;
  }
}

class JsonRpcWebSocketClient {
  constructor(
    url,
    {
      bearerToken = null,
      timeoutMs = DEFAULT_TIMEOUT_MS,
      onNotification = null,
      onRequest = null,
      onClose = null,
      logger = null,
    } = {},
  ) {
    this.url = url;
    this.bearerToken = bearerToken;
    this.timeoutMs = timeoutMs;
    this.onNotification = onNotification;
    this.onRequest = onRequest;
    this.onClose = onClose;
    this.logger = logger;
    this.nextId = 1;
    this.pending = new Map();
    this.ws = null;
  }

  connect() {
    if (this.ws) {
      return Promise.resolve();
    }
    const headers = {};
    if (this.bearerToken) {
      headers.Authorization = `Bearer ${this.bearerToken}`;
    }
    const startedAt = Date.now();
    this.logger?.info("upstream.connect_start", {
      url: this.url,
      bearerConfigured: Boolean(this.bearerToken),
    });
    return new Promise((resolve, reject) => {
      const ws = new WebSocket(this.url, { headers });
      const timer = setTimeout(() => {
        this.logger?.warn("upstream.connect_timeout", {
          url: this.url,
          durationMs: Date.now() - startedAt,
        });
        reject(new Error(`timed out connecting to ${this.url}`));
        ws.close();
      }, this.timeoutMs);
      ws.on("open", () => {
        clearTimeout(timer);
        this.ws = ws;
        this.logger?.info("upstream.connect_open", {
          url: this.url,
          durationMs: Date.now() - startedAt,
        });
        resolve();
      });
      ws.on("message", (data) => this.handleMessage(data));
      ws.on("error", (error) => {
        clearTimeout(timer);
        this.rejectAll(error);
        this.logger?.error("upstream.websocket_error", {
          url: this.url,
          error,
        });
        if (!this.ws) {
          reject(error);
        }
      });
      ws.on("close", () => {
        this.rejectAll(new Error(`websocket closed: ${this.url}`));
        if (this.ws === ws) {
          this.ws = null;
        }
        this.logger?.warn("upstream.websocket_closed", {
          url: this.url,
        });
        this.onClose?.();
      });
    });
  }

  handleMessage(data) {
    let message;
    try {
      message = JSON.parse(data.toString());
    } catch {
      this.logger?.warn("upstream.invalid_json", {
        url: this.url,
        bytes: data?.byteLength,
      });
      return;
    }
    if (message.id !== undefined && this.pending.has(String(message.id))) {
      const pending = this.pending.get(String(message.id));
      this.pending.delete(String(message.id));
      clearTimeout(pending.timer);
      if (message.error) {
        this.logger?.warn("upstream.request_failed", {
          url: this.url,
          method: pending.method,
          durationMs: Date.now() - pending.startedAt,
          code: message.error.code,
        });
        pending.reject(new JsonRpcUpstreamError(pending.method, message.error));
      } else {
        this.logger?.debug("upstream.request_succeeded", {
          url: this.url,
          method: pending.method,
          durationMs: Date.now() - pending.startedAt,
        });
        pending.resolve(message.result);
      }
      return;
    }

    if (message.method && message.id !== undefined) {
      this.onRequest?.(message);
      return;
    }

    if (message.method) {
      this.onNotification?.(message);
    }
  }

  request(method, params = undefined) {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      this.logger?.warn("upstream.request_rejected", {
        url: this.url,
        method,
        reason: "not_connected",
      });
      return Promise.reject(new Error(`not connected: ${this.url}`));
    }
    const id = String(this.nextId);
    this.nextId += 1;
    const payload = { jsonrpc: "2.0", id, method };
    if (params !== undefined) {
      payload.params = params;
    }
    this.ws.send(JSON.stringify(payload));
    const startedAt = Date.now();
    this.logger?.debug("upstream.request_sent", {
      url: this.url,
      method,
      id,
    });
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        this.logger?.warn("upstream.request_timeout", {
          url: this.url,
          method,
          id,
          durationMs: Date.now() - startedAt,
        });
        reject(new Error(`timed out waiting for ${method} from ${this.url}`));
      }, this.timeoutMs);
      this.pending.set(id, { method, resolve, reject, timer, startedAt });
    });
  }

  notify(method, params = undefined) {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      return;
    }
    const payload = { jsonrpc: "2.0", method };
    if (params !== undefined) {
      payload.params = params;
    }
    this.ws.send(JSON.stringify(payload));
    this.logger?.debug("upstream.notification_sent", {
      url: this.url,
      method,
    });
  }

  sendRaw(message) {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      return false;
    }
    this.ws.send(typeof message === "string" ? message : JSON.stringify(message));
    return true;
  }

  isOpen() {
    return this.ws?.readyState === WebSocket.OPEN;
  }

  close() {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }

  rejectAll(error) {
    for (const pending of this.pending.values()) {
      clearTimeout(pending.timer);
      pending.reject(error);
    }
    this.pending.clear();
  }
}

export {
  JsonRpcUpstreamError,
  JsonRpcWebSocketClient,
};

#!/usr/bin/env node
