public enum DockTabID: String, CaseIterable, Identifiable, Equatable, Sendable {
    case all
    case needsMe
    case running
    case limited
    case agents

    public var id: String { rawValue }

    public var title: String {
        switch self {
        case .all:
            return "All"
        case .needsMe:
            return "Needs me"
        case .running:
            return "Running"
        case .limited:
            return "Limited"
        case .agents:
            return "Agents"
        }
    }

    public func includes(_ row: DockRowViewModel) -> Bool {
        switch self {
        case .all:
            return row.origin.kind == .humanInteractive
        case .needsMe:
            return row.origin.kind == .humanInteractive && row.status == .needsMe
        case .running:
            return row.origin.kind == .humanInteractive
                && (
                    row.status == .needsMe
                        || row.status == .running
                        || row.status == .idle
                        || row.status == .failed
                )
        case .limited:
            return row.origin.kind == .humanInteractive && row.status == .limited
        case .agents:
            return row.origin.kind != .humanInteractive
        }
    }
}

