            ws_token_sha256: Some("ab".repeat(32)),
            ..Default::default()
        }
        .try_into_settings()
        .expect_err("capability-token mode should reject multiple token sources");
        assert!(
            err.to_string().contains("mutually exclusive"),
            "unexpected error: {err}"
        );
